import {validProtectionArchive} from './archive.mjs';
export class ProtectionRepository{
  constructor({indexedDB=globalThis.indexedDB}={}){this.indexedDB=indexedDB;this.db=null;this.current=null;this.persistence='memory';}
  async open(){if(this.db)return this.db;if(!this.indexedDB)throw Error('protection_storage_unavailable');this.db=await new Promise((resolve,reject)=>{const q=this.indexedDB.open('w-alerter.protection.v1',1);q.onupgradeneeded=()=>q.result.createObjectStore('archives');q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error);q.onblocked=()=>reject(Error('protection_storage_blocked'));});return this.db;}
  async load(){try{const db=await this.open(),data=await new Promise((resolve,reject)=>{const q=db.transaction('archives').objectStore('archives').get('active');q.onsuccess=()=>resolve(q.result||null);q.onerror=()=>reject(q.error);});if(validProtectionArchive(data)){this.current=data;this.persistence='indexeddb';}}catch{this.persistence='memory';}return this.current;}
  async save(data){if(!validProtectionArchive(data))throw Error('invalid_local_protection_archive');try{const db=await this.open();await new Promise((resolve,reject)=>{const tx=db.transaction('archives','readwrite');tx.objectStore('archives').put(data,'active');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});this.persistence='indexeddb';}catch{this.persistence='memory';}this.current=data;return this.persistence;}
  async remove(){try{const db=await this.open();await new Promise((resolve,reject)=>{const tx=db.transaction('archives','readwrite');tx.objectStore('archives').delete('active');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}catch(error){if(this.persistence==='indexeddb')throw error;}this.current=null;}
}
